const rowHeight=91+11+Math.max(...cards.map(c=>Math.min(2,c.nameLines.length)))*12+8+Math.max(...cards.map(c=>Math.min(3,c.noteLines.length)))*12+16;
ensure(rowHeight);
for(let j=0;j<cards.length;j++){const {i,index,image,noteLines,nameLines}=cards[j],x=34+j*181;rect(x,y,165,91,C.pale);if(image){const r=Math.min(165/image.naturalWidth,91/image.naturalHeight);const w=image.naturalWidth*r,h=image.naturalHeight*r;ctx.drawImage(image,x+(165-w)/2,y+(91-h)/2,w,h)}else{text(x+43,y+38,'现场照片位置',8,C.muted);text(x+28,y+55,i.samples?.length?'仅示例附件，未附实拍':'未上传现场照片',7,C.muted)}text(x,y+103,String(index+1).padStart(2,'0'),9,C.blue);nameLines.slice(0,2).forEach((line,n)=>text(x+21,y+102+n*12,line,9,C.ink,500));const ny=y+110+Math.min(2,nameLines.length)*12;noteLines.slice(0,3).forEach((line,n)=>text(x,ny+n*12,line,8,C.muted));if(noteLines.length>3)text(x,ny+36,'完整说明见续页',7,C.blue)}y+=rowHeight;
