function metricMarkup(n,v,f){return `<button type="button" class="metric cursor-interaction" data-filter="${f}"><span class="muted">${n}</span><span class="value ${f==='超期'||f==='安全风险'?'warn':''}">${v}</span><small>查看相关工单</small></button>`}
