function contractStatus(d){if(d.contractType==='无固定截止日')return '无固定截止日';if(!d.contractStart||!d.contractEnd)return '待核实';return today<d.contractStart?'未生效':today>d.contractEnd?'已到期':'有效期内'}
function warrantyStatus(d,asOf=today){if(d.warrantyPolicy==='无保修')return '无保修约定';if(d.warrantyPolicy!=='有保修'||!d.warrantyStart||!d.warrantyEnd||!d.warrantyBasis||d.warrantyBasis==='待核实')return '待核实';if(asOf<d.warrantyStart)return '尚未起保';if(asOf>d.warrantyEnd)return '保修期已过';const limit=new Date(asOf+'T00:00:00Z');const day=limit.getUTCDate();limit.setUTCDate(1);limit.setUTCMonth(limit.getUTCMonth()+1);const last=new Date(Date.UTC(limit.getUTCFullYear(),limit.getUTCMonth()+1,0)).getUTCDate();limit.setUTCDate(Math.min(day,last));return '保修期内'}
function warrantyDisplay(d){let html=statusTag(warrantyStatus(d));if(warrantyStatus(d)==='保修期内'){const limit=new Date(today+'T00:00:00Z');const day=limit.getUTCDate();limit.setUTCDate(1);limit.setUTCMonth(limit.getUTCMonth()+1);const last=new Date(Date.UTC(limit.getUTCFullYear(),limit.getUTCMonth()+1,0)).getUTCDate();limit.setUTCDate(Math.min(day,last));if(d.warrantyEnd<=limit.toISOString().slice(0,10)){const days=Math.round((Date.parse(d.warrantyEnd)-Date.parse(today))/86400000);html+=` <span class="warranty-reminder">${days===0?'提醒：今天到期':'提醒：还有 '+days+' 天到期'}</span>`}}return html;}
function statusTag(s){const tone=/已到期|保修期已过|无保修|一个月内/.test(s)?'orange':/有效期内|保修期内/.test(s)?'green':'';return `<span class="tag ${tone}">${esc(s)}</span>`}
function orderKey(d){return JSON.stringify([d.project,d.order])}
