$('#yw-order').innerHTML='<option>全部项目 / 订单</option>'+groups.map(d=>`<option value="${esc(orderKey(d))}">${esc(d.project)} / ${esc(d.order||'订单待补充')}</option>`).join('');$('#yw-order').value=state.order;
