root.addEventListener('click',async e=>{
if(e.target.closest('#yifun-hub'))return;
const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-af-analysis'))return;captureDepartmentEdits();
if(b.hasAttribute('data-save-order-plan')){const form=$('#yw-engineering-form'),d=data.find(x=>x.id===form?.dataset.workId),raw=Object.fromEntries(new FormData(form));if(!d)return;if(!validDate(raw.orderPlanned)||raw.orderPlanned<d.reported||!orderingGroups[raw.orderGroup]?.includes(raw.engineer)){$('#yw-engineering-error').textContent='请先选择下单组、组内下单人并填写有效的下单计划完成时间。';return;}d.orderPlanned=raw.orderPlanned;d.orderGroup=raw.orderGroup;d.orderAssignee=raw.engineer;captureDepartmentEdits();state.selected=null;render();notice('下单计划已保存，尚未转入生产采购；临近到期会在本页提醒。');persist();return;}
if(b.dataset.operationId){toggleAtCurrentPosition(b,()=>{state.selected=state.selected===b.dataset.operationId?null:b.dataset.operationId;render();});persist();return;}
if(b.dataset.submitDraft){const items=data.filter(d=>d.batchId===b.dataset.submitDraft&&d.submitted===false);for(const d of items){d.submitted=true;d.stageEnteredAt=today;d.stage='审核';d.history.push({at:today,actor:d.trackingOwner,action:'专员正式提交整单，进入审核中心'});}if(intakeBatch?.id===b.dataset.submitDraft)intakeBatch=null;render();notice('本次报修 '+items.length+' 条问题已正式提交审核。');return;}
if(b.hasAttribute('data-toggle-review-item')){const id=b.dataset.toggleReviewItem;root.querySelectorAll('.yw-review-item-form').forEach(form=>{if(!collapsedReviewItems.has(form.dataset.workId))captureReviewEdits(form)});if(collapsedReviewItems.has(id)){const d=data.find(x=>x.id===id);if(d)batchItems(d).forEach(x=>collapsedReviewItems.add(x.id));collapsedReviewItems.delete(id);}else collapsedReviewItems.add(id);render();return;}
if(b.hasAttribute('data-edit-review')){const d=data.find(x=>x.id===b.dataset.editReview);if(d&&!d.review?.approved){reviewEdits.set(d.id,{...d.reviewDraft});render()}return}
if(b.hasAttribute('data-dispatch-batch')){dispatchReviewBatch(b.dataset.dispatchBatch);return}
if(b.hasAttribute('data-review-media')){const d=data.find(x=>x.id===b.dataset.reviewMedia),f=d?.attachments?.[Number(b.dataset.mediaIndex)];const viewer=[...root.querySelectorAll('[data-media-view]')].find(el=>el.dataset.mediaView===d?.id);if(f&&viewer){viewer.hidden=false;viewer.innerHTML=`<div class="toolbar"><small>${esc(f.name)}</small><button type="button" class="cursor-interaction" data-close-media>收起大图</button></div>${f.type.startsWith('image/')?`<img src="${esc(f.url)}" alt="${esc(f.name)}">`:`<video src="${esc(f.url)}" controls autoplay></video>`}`}return}
if(b.hasAttribute('data-close-media')){b.closest('[data-media-view]').hidden=true;b.closest('[data-media-view]').innerHTML='';return}

if(b.dataset.reviewTab){state.reviewTab=b.dataset.reviewTab;state.selected=null;render();persist();return}
if(b.dataset.reviewId){root.querySelectorAll('.yw-review-item-form').forEach(captureReviewEdits);toggleAtCurrentPosition(b,()=>{state.selected=state.selected===b.dataset.reviewId?null:b.dataset.reviewId;render();});persist();return}
if(b.dataset.engineeringId){toggleAtCurrentPosition(b,()=>{state.selected=state.selected===b.dataset.engineeringId?null:b.dataset.engineeringId;render();});persist();return}
if(b.hasAttribute('data-go-engineering')){state.nav='工程下单中心';state.filter='工程下单';render();persist();return}
if(b.dataset.projectOrder){const record=commercialRecords.find(d=>d.order===b.dataset.projectOrder);if(record)applyProject(record);return}
if(b.hasAttribute('data-remove-upload')){const i=Number(b.dataset.removeUpload);if(draftUploads[i]){URL.revokeObjectURL(draftUploads[i].url);draftUploads.splice(i,1);renderUploads()}return}
if(b.dataset.entry){entryMode=b.dataset.entry;state.selected=null;render();if(entryMode==='manual')updateAutoWarranty(false);return}
if(b.hasAttribute('data-entry-cancel')){entryMode=null;render();return}
if(b.hasAttribute('data-template')){b.disabled=true;try{await downloadTemplate()}catch(error){$('#yw-import-errors').textContent=error.message}finally{b.disabled=false}return}
if(b.hasAttribute('data-import-confirm')){if(pending.length)addRecords(pending,'表格导入');return}
if(b.dataset.nav){state.nav=b.dataset.nav;if(state.nav==='售后审核中心'){state.reviewTab='待审核';state.customer='全部客户';state.order='全部项目 / 订单';}const map={'售后审核中心':'审核','工程下单中心':'工程下单','采购中心':'生产采购','仓库与物流中心':'发货物流','安装中心':'现场处理'};state.filter=map[state.nav]||'全部';state.selected=null;entryMode=null;$('#yw-notice').hidden=true}
else if(b.dataset.filter){state.filter=b.dataset.filter;state.selected=null}
else if(b.dataset.id){state.selected=b.dataset.id}
else if(b.hasAttribute('data-close'))state.selected=null;
else return;
render();persist();
});
const operationStages={'采购中心':['采购'],'生产中心':['生产采购'],'仓库与物流中心':['发货物流'],'安装中心':['现场处理','客户验收','负责人复核'],'验收关闭中心':['客户验收','负责人复核'],'产品改善中心':['改善跟踪'],'售后数据中心':['已关闭'],'财务中心':[]};
const operationPanel=document.createElement('section');operationPanel.id='yw-operation-center';operationPanel.className='panel';$('#yw-notice').before(operationPanel);
const draftPanel=document.createElement('section');draftPanel.className='panel';$('#yw-entry').after(draftPanel);
const operationEdits=new Map();
root.addEventListener('input',e=>{const f=e.target.closest('#yw-operation-form');if(f)operationEdits.set(f.dataset.workId,Object.fromEntries(new FormData(f)));});
const improvementTasks=[];
function renderDrafts(show){draftPanel.hidden=!show;if(!show)return;const drafts=data.filter(d=>d.submitted===false),groups=[...new Set(drafts.map(d=>d.batchId))];draftPanel.innerHTML='<div class="toolbar"><h2>登记草稿 · '+groups.length+' 单</h2><small>正式提交后才会出现在审核中心</small></div>'+groups.map(id=>{const a=drafts.filter(d=>d.batchId===id),d=a[0];return `<div class="review-ticket"><div><p>${esc(d.customer)} · ${esc(d.project)}</p><small>${a.length} 条已保存问题 · ${esc(d.trackingOwner)}</small>${a.map(x=>`<p>${esc(x.product)}：${esc(x.issue)}</p>`).join('')}</div><button type="button" data-submit-draft="${esc(id)}">确认整单并提交审核</button></div>`}).join('');}
function nextLabel(d){return ({'部门处理':'保存处理结果 → 客户验收','采购':d.purchase?.status==='已采购'?'填写物流与单号 → 提交生产部':'确认采购物品 → 登记已采购','生产采购':d.production?.status==='生产中'?'生产中 → 完成后交仓库打包发货':'待接收工程生产任务','品质检验':'检验通过 → 发货物流','发货物流':d.shipment?'确认签收 → 安装服务':'登记发运，等待签收','现场处理':'提交服务结果 → 客户验收','客户验收':'客户确认 → 负责人复核','负责人复核':'复核通过 → 关闭归档'})[d.stage]||'查看归档';}
function renderOperations(show){operationPanel.hidden=!show;if(!show)return;if(state.nav==='财务中心'){renderFinanceCenter();return;}if(state.nav==='生产中心'){renderProductionQueue();return;}for(const sel of ['.totals','.metrics','#yw-stage-panel','.bottom','.detail'])$(sel).hidden=true;mainTable.closest('section').hidden=true;
$('#yw-subtitle').textContent=state.nav==='售后审核中心'?'审核方案 · 部门协同 · 处理结果 · 统一交接':'接收本环节待办 · 查看完整资料 · 记录结果后转交下一环节';
if(state.nav==='产品改善中心'){operationPanel.innerHTML='<div class="toolbar"><h2>产品改善 · 独立跟踪</h2></div>'+improvementTasks.map(t=>`<details class="review-problem" name="yw-improvement-accordion"><summary>${t.id} · ${esc(t.project)} · ${esc(t.status)}</summary><small>${t.id} · ${esc(t.project)}</small><p>${esc(t.issue)}</p><p>${esc(t.owner)} · 计划 ${t.planned} · ${t.status}</p><form data-improvement="${t.id}"><label class="form-field">验证结果<textarea name="result" required>${esc(t.result)}</textarea></label><button type="submit">保存验证完成</button></form></details>`).join('');return;}
const rows=data.filter(d=>d.submitted!==false&&scopeRecord(d)&&(state.nav==='售后审核中心'?['部门处理']:operationStages[state.nav]).includes(d.stage));
operationPanel.innerHTML=`<div class="toolbar"><h2>${state.nav==='售后数据中心'?'已关闭归档':'本环节待办'} · ${rows.length} 条问题</h2><small>超期 ${rows.filter(overdue).length} 条</small></div><div class="review-flow">专员提交 → 审核与协同处理 → 工程下单（需要配件时） → 生产 → 发货物流 → 安装服务 → 客户验收 → 负责人复核 → 关闭</div><div class="review-queue">${rows.map(d=>`<div class="review-ticket"><div class="review-ticket-content"><small>${esc(d.customer)} · ${esc(d.project)} · ${esc(d.workNo)}</small><p>${esc(d.issue)} <span class="tag">${esc(d.stage)}</span></p><small>${esc(d.department||'售后部')} · ${esc(d.owner)} · 计划 ${esc(d.planned)} ${overdue(d)?' · 已超期':''}</small><p>${esc(nextLabel(d))}</p></div><button type="button" data-operation-id="${d.id}" aria-expanded="${state.selected===d.id}">${state.selected===d.id?'收起本条':'展开 / 处理'}</button></div>`).join('')||'<p class="muted">暂无本环节待办。</p>'}</div><div id="yw-operation-editor"></div>`;
const d=rows.find(d=>d.id===state.selected);if(!d)return;const editor=$('#yw-operation-editor');if(d.stage==='生产采购'){renderProductionEditor(d,editor);return;}editor.innerHTML=reviewProblem(d)+reviewMedia(d)+previousRepairs(d)+`<div class="review-problem"><small>审核处理方法 / 工程资料</small><p>${esc(d.review?.method||'待补充')}</p><p>${esc(d.engineering?.orderNumber||'无需物料下单')} · ${esc(d.engineering?.items||'')}</p><p>下单组：${esc(d.engineering?.orderGroup||'待补充')} · 下单人：${esc(d.engineering?.engineer||'待补充')} · 下单计划完成：${esc(d.engineering?.plannedAt||'待补充')} · 下单实际完成：${esc(d.engineering?.completedAt||'待补充')}</p></div>`+reviewHistory(d);
if(d.stage==='已关闭'){editor.insertAdjacentHTML('beforeend',`<p class="tag green">已关闭 · ${esc(d.actual)}</p>`);return;}
if(d.stage==='采购'){renderPurchaseEditor(d,editor);return;}
if(d.stage==='生产采购'){renderProductionEditor(d,editor);return;}
if(d.awaitingAssignment){editor.insertAdjacentHTML('beforeend',`<form id="yw-assign-execution" class="review-form" data-work-id="${d.id}"><div class="review-flow">工程已提交至${esc(departmentName(d.department))}，请本部门接单并安排执行。</div><div class="form-grid"><label class="form-field">本部门负责人 *<input name="owner" required maxlength="100"></label><label class="form-field">本部门计划完成时间 *<input name="planned" type="date" required min="${today}"></label></div><div class="import-errors" role="alert"></div><button type="submit" class="primary">确认接单并安排</button></form>`);return;}
const raw=operationEdits.get(d.id)||{},input=(k,label,type='text',value='')=>`<label class="form-field">${label} *<input name="${k}" type="${type}" required value="${esc(raw[k]??value)}"></label>`;
let extras='';if(d.stage==='发货物流')extras=input('carrier','物流公司','text',d.shipment?.carrier||'')+input('tracking','运单号','text',d.shipment?.tracking||'')+input('address','收货地址','text',d.address);if(d.stage==='现场处理')extras=`<label class="form-field">执行方式<select name="serviceMode">${methods.slice(1).map(m=>`<option ${m===(raw.serviceMode||d.method)?'selected':''}>${m}</option>`).join('')}</select></label>`;
if(d.stage==='客户验收')extras=input('customerContact','客户确认人','text',d.contact);
editor.insertAdjacentHTML('beforeend',`<form id="yw-operation-form" class="review-form" data-work-id="${d.id}" data-stage="${d.stage}"><div class="form-grid">${input('actor','本环节处理人','text',d.owner)}${extras}<label class="form-field wide">${d.stage==='客户验收'?'客户验收意见':d.stage==='品质检验'?'检验项目与结果':'处理结果 / 交接说明'} *<textarea name="result" required maxlength="3000">${esc(raw.result||'')}</textarea></label><label class="form-field">处理结论<select name="decision"><option value="pass">${d.stage==='发货物流'&&d.shipment?'客户已签收':'完成 / 通过'}</option>${['品质检验','客户验收','负责人复核'].includes(d.stage)?'<option value="return">不通过，退回处理</option>':''}</select></label>${d.stage==='负责人复核'?'':input('nextOwner','下一环节负责人','text',d.stage==='客户验收'?'赵主管':'')+input('planned','下一环节计划完成','date','2026-10-17')}</div><p class="review-flow">${esc(nextLabel(d))}${d.shipment?' · 运单 '+esc(d.shipment.tracking):''}</p><div class="import-errors" role="alert"></div><button type="submit" class="primary">${esc(nextLabel(d))}</button></form>`);
}
function submitOperation(form){const d=data.find(d=>d.id===form.dataset.workId),r=Object.fromEntries(new FormData(form));const error=form.querySelector('.import-errors');if(!d||d.stage!==form.dataset.stage){error.textContent='工单阶段已变化，请刷新查看。';return;}if(!r.actor?.trim()||!r.result?.trim()||(d.stage!=='负责人复核'&&(!r.nextOwner?.trim()||!validDate(r.planned)||r.planned<today))){error.textContent='请补齐处理结果、处理人、下一环节负责人及有效计划日期。';return;}if(d.stage==='生产采购'&&!d.engineering?.confirmed&&!d.purchase){error.textContent='缺少工程正式下单记录，不能进入生产。';return;}
const old=d.stage;let target=({'部门处理':'客户验收','生产采购':'品质检验','品质检验':'发货物流','发货物流':d.shipment?'现场处理':'发货物流','现场处理':'客户验收','客户验收':'负责人复核','负责人复核':'已关闭'})[old];
if(r.decision==='return')target=old==='品质检验'?'生产采购':'现场处理';
if(old==='发货物流'){if(!r.carrier?.trim()||!r.tracking?.trim()||!r.address?.trim()){error.textContent='请补齐物流公司、运单号和收货地址。';return;}d.shipment={carrier:r.carrier,tracking:r.tracking,address:r.address,received:!!d.shipment};}
if(old==='现场处理'){d.method=r.serviceMode;d.installer=r.actor;}if(old==='客户验收'&&!r.customerContact?.trim()){error.textContent='请填写客户确认人。';return;}
d.history.push({at:today,actor:r.actor,action:old+'：'+r.result+'；'+(r.decision==='return'?'不通过，退回':'完成，转')+target});d.feedback+='\n['+today+'] '+old+'：'+r.result;d.stageEnteredAt=today;d.stage=target;d.next=nextLabel(d);d.department=({'现场处理':'安装服务部','品质检验':'品质部','发货物流':'物流部','客户验收':'售后部','负责人复核':'售后部','生产采购':d.engineering?.destination||'工厂'})[target]||'售后部';if(target==='已关闭')d.actual=today;else{d.owner=r.nextOwner;d.planned=r.planned;}operationEdits.delete(d.id);departmentEdits.delete(form.id+':'+d.id);state.selected=null;render();notice(old==='发货物流'&&target==='发货物流'?'发运已登记，签收后再转安装服务。':'处理结果已保存，工单已转至'+target+'。');persist();}
root.addEventListener('submit',e=>{
if(e.target.closest('#yifun-hub'))return;if(e.target.dataset.improvement){e.preventDefault();const t=improvementTasks.find(t=>t.id===e.target.dataset.improvement);t.result=String(new FormData(e.target).get('result')||'').trim();if(t.result){t.status='验证完成';render();notice('产品改善验证结果已保存。');}}});

function renderProductionEditor(d,editor){const status=d.production?.status||'待接收';editor.innerHTML=`<div class="review-problem"><div class="toolbar"><h2>生产任务</h2><span class="tag">${esc(status)}</span></div><p>项目：${esc(d.project)} · ${esc(d.workNo)}</p><p>要做什么：${esc(d.engineering?.items||d.review?.purchaseItems||d.review?.method||d.issue)}</p><p>型号：${esc(d.review?.purchaseModel||d.product||'待补充')} · 线下生产单：${esc(d.engineering?.orderNumber||'待补充')}</p></div><form id="yw-production-form" class="review-form" data-work-id="${d.id}"><div class="entry-actions"><button type="submit" name="productionAction" value="receive" formnovalidate ${status!=='待接收'?'disabled':''}>${status==='待接收'?'确认接收':'已接收'}</button><button type="button" data-production-step="start" ${status==='待接收'?'disabled':''}>生产中</button><button type="button" data-production-step="finish" ${status!=='生产中'?'disabled':''}>生产完成，交接仓库打包</button></div><label class="form-field production-cost-field">生产费用（元，本条合计） *<input name="amount" type="number" min="0" step="0.01" value="${esc(d.production?.amountCents!=null?d.production.amountCents/100:'')}" placeholder="新增加工费，不含采购费"></label><div class="form-grid" data-production-start hidden><label class="form-field">预计完成时间 *<input name="estimatedAt" type="date" min="${today}" value="${esc(d.production?.estimatedAt||'')}"></label><div class="entry-actions"><button type="submit" name="productionAction" value="start">保存预计完成时间</button></div></div><div class="form-grid" data-production-finish hidden><label class="form-field">实际完成 / 交接时间 *<input name="completedAt" type="date" max="${today}"></label><div class="entry-actions"><button type="submit" name="productionAction" value="finish">确认交接仓库打包</button></div></div><div class="import-errors" role="alert"></div><p class="muted">${d.production?.receivedAt?'接收：'+esc(d.production.receivedAt):''}${d.production?.estimatedAt?' · 预计完成：'+esc(d.production.estimatedAt):''}</p></form>${reviewHistory(d)}<details class="review-problem"><summary>查看原售后问题、照片与维修记录</summary>${reviewProblem(d)}${reviewMedia(d)}${previousRepairs(d)}</details>`;}
root.addEventListener('click',e=>{const b=e.target.closest('[data-production-step]');if(!b)return;const form=b.closest('form'),start=b.dataset.productionStep==='start';form.querySelector('[data-production-start]').hidden=!start;form.querySelector('[data-production-finish]').hidden=start;});
function renderPurchaseEditor(d,editor){
const order=d.purchase||{},raw=departmentEdits.get('yw-purchase-form:'+d.id)||order;
editor.insertAdjacentHTML('beforeend',`<div class="review-problem"><h2>审核采购需求</h2><p>采购物品 / 规格 / 数量：${esc(d.review?.purchaseItems||d.engineering?.items||'待审核人补充')}</p><p>型号：${esc(d.review?.purchaseModel||'未提供')}</p></div><form id="yw-purchase-form" class="review-form" data-work-id="${d.id}"><div class="form-grid"><label class="form-field">采购处理人 *<input name="buyer" required value="${esc(raw.buyer||d.owner)}"></label><label class="form-field">处理结论 *<select name="status" required><option value="">请选择</option><option ${raw.status==='仓库有库存'?'selected':''}>仓库有库存</option><option ${raw.status==='已采购'?'selected':''}>已采购</option></select></label><label class="form-field" data-purchase-tracking ${raw.status==='已采购'?'':'hidden'}>单号 *<input name="tracking" ${raw.status==='已采购'?'required':''} value="${esc(raw.tracking||'')}" placeholder="填写采购 / 物流单号"></label><label class="form-field">采购费用（元，本条合计） *<input name="amount" type="number" min="0" step="0.01" required value="${esc(raw.amount??'')}" placeholder="填写本条实际采购金额"></label><label class="form-field wide">处理备注<textarea name="notes">${esc(raw.notes||'')}</textarea></label></div><div class="review-flow">确认完工后自动转生产部，实际完成时间和处理用时由系统记录。</div><div class="import-errors" role="alert"></div><button type="submit" class="primary">确认完工并转生产部</button></form>`);
}
function costCents(value){const raw=String(value??'').trim();if(!/^\d+(\.\d{1,2})?$/.test(raw))return null;const amount=Math.round(Number(raw)*100);return Number.isSafeInteger(amount)&&amount>=0?amount:null;}
function syncDepartmentCost(d,category,amount){window.__yifunHub.shared.finance.upsertDepartmentCost({id:'DEPT-'+category+'-'+d.id,orderId:d.order||d.project,project:d.project,serviceId:d.workNo,date:today,category,name:d.product||d.issue,reason:d.issue,person:category==='采购'?d.purchase.buyer:'生产部',trackingOwner:d.trackingOwner,source:category+'/'+d.workNo,basis:category==='采购'?'本条采购总费用；单号 '+(d.purchase.tracking||'库存领用'):'本条新增生产加工费，不含已登记采购材料费',amount,status:d.stage});}
function submitPurchase(form){const d=data.find(x=>x.id===form.dataset.workId),r=Object.fromEntries(new FormData(form)),error=form.querySelector('.import-errors');if(!d||d.stage!=='采购'||(window.__yifunAccess&&!window.__yifunAccess.canEditRecord(d)))return;if(!r.buyer?.trim()||!['仓库有库存','已采购'].includes(r.status)){error.textContent='请填写采购处理人并选择处理结论。';return;}if(r.status==='已采购'&&!r.tracking?.trim()){error.textContent='已采购请填写单号。';return;}const amountCents=costCents(r.amount);if(amountCents===null){error.textContent='请填写有效采购费用，最多两位小数；无新增费用可填0。';return;}const started=d.stageEnteredAt||null;const duration=started?Math.max(0,Math.round((Date.parse(today)-Date.parse(started))/86400000)):null;d.purchase={...r,amountCents,completedAt:today,startedAt:started,durationDays:duration};d.history.push({at:today,actor:r.buyer,action:'采购完工：'+r.status+(r.status==='已采购'?'；单号 '+r.tracking:'')+'；实际完成 '+today+'；用时 '+(duration===null?'接收时间待补充':duration+' 天')+'；自动提交生产部'});d.stageEnteredAt=today;d.stage='生产采购';d.department='工厂';d.owner='待部门分派';d.planned='';d.awaitingAssignment=true;d.next='生产部接收物料并安排生产';syncDepartmentCost(d,'采购',amountCents);departmentEdits.delete(form.id+':'+d.id);state.selected=null;render();notice('采购已完工并转生产部，采购费用已同步到财务中心待核对。');persist();}
root.addEventListener('change',e=>{if(e.target.matches('#yw-purchase-form [name="status"]')){const form=e.target.form,yes=e.target.value==='已采购';form.querySelector('[data-purchase-tracking]').hidden=!yes;form.elements.tracking.required=yes;captureDepartmentEdits();}});

const trackingPanel=document.createElement('section');trackingPanel.className='panel';trackingPanel.id='yw-order-tracking';draftPanel.after(trackingPanel);
let trackingSelected=null;
function productionOrderDetails(items){const tasks=items.filter(d=>d.engineering||d.stage==='生产采购'||d.production);if(!tasks.length)return '<p class="muted">本订单暂无已下达的生产任务。</p>';return '<div class="table-wrap"><table><thead><tr><th>设备 / 产品</th><th>生产任务 / 规格数量</th><th>工程单号</th><th>生产状态</th><th>预计完成</th><th>实际完成 / 交接仓库</th></tr></thead><tbody>'+tasks.map(d=>`<tr><td>${esc(d.product||'待补充')}</td><td>${esc(d.engineering?.items||d.review?.purchaseItems||d.review?.method||d.issue)}</td><td>${esc(d.engineering?.orderNumber||'待补充')}</td><td>${esc(d.production?.status||(d.stage==='生产采购'?'待接收':d.stage==='工程下单'?'待工程下单':'待生产记录'))}</td><td>${esc(d.production?.estimatedAt||'待安排')}</td><td>${esc(d.production?.completedAt||'尚未完成')}</td></tr>`).join('')+'</tbody></table></div>';}
function trackingIssue(x){return `<details class="review-problem" name="yw-tracking-issues"><summary>${esc(x.product||x.workNo)} · ${esc(x.issue)} · ${esc(x.stage)}${overdue(x)?' · 已超期':''}</summary>${new URLSearchParams(location.search).has('record')?`<button type="button" data-af-analysis="${esc(x.id)}">故障与根因追踪</button>`:''}<div class="detail-grid">${detailField('当前责任部门',x.department||'售后审核')}${detailField('当前负责人',x.owner)}${detailField('当前环节计划完成',x.stage==='工程下单'?x.orderPlanned||x.planned:x.planned)}${detailField('售后实际完成',x.actual||'尚未完成')}${detailField('售后全程跟踪人',x.trackingOwner)}${detailField('下一步',x.next)}${detailField('工程计划 / 实际完成',(x.engineering?.plannedAt||x.orderPlanned||'待安排')+' / '+(x.engineering?.completedAt||'未完成'))}${detailField('采购状态',x.purchase?.status||'暂无采购记录')}${detailField('采购费用',x.purchase?.amountCents!=null?'¥'+(x.purchase.amountCents/100).toFixed(2):'待填报')}${detailField('生产费用',x.production?.amountCents!=null?'¥'+(x.production.amountCents/100).toFixed(2):'待填报')}${detailField('物流公司 / 单号',x.purchase?(x.purchase.carrier||'待填写')+' / '+(x.purchase.tracking||'待填写'):x.shipment?x.shipment.carrier+' / '+x.shipment.tracking:'尚未发运')}</div><details class="tracking-history"><summary>流转记录与照片</summary><div class="review-history">${esc(x.reported)} · 售后登记${(x.history||[]).map(h=>'<p>'+esc(h.at+' · '+h.actor+'：'+h.action)+'</p>').join('')}</div>${reviewMedia(x)}</details></details>`;}
function departmentTiming(items,stage){const active=items.filter(x=>x.stage===stage);if(!active.length)return '';const plans=active.map(x=>stage==='工程下单'?x.orderPlanned||x.planned:x.planned).filter(Boolean).sort();const starts=active.map(x=>x.stageEnteredAt).filter(Boolean).sort();let text=starts.length?'已用'+Math.max(0,Math.round((Date.parse(today)-Date.parse(starts[0]))/86400000))+'天':'接收时间待记录';if(plans.length){const days=Math.round((Date.parse(plans[0])-Date.parse(today))/86400000);text+=' · '+(days<0?'<span class="timing-overdue">超期'+(-days)+'天</span>':days===0?'<span class="timing-today">今日到期</span>':'剩'+days+'天');}else text+=' · 待排期';return '<small class="department-duration">'+text+'</small>'+(plans.length?'<small class="department-plan">计划 '+esc(plans[0].slice(5))+'</small>':'');}
function renderTracking(show){
trackingPanel.hidden=!show;if(!show)return;
const rows=data.filter(d=>d.submitted!==false&&scopeRecord(d));
const groups=[...new Map(rows.map(d=>[JSON.stringify([d.customer,d.project,d.order]),rows.filter(x=>x.customer===d.customer&&x.project===d.project&&x.order===d.order)])).values()];
const count=(items,stage)=>items.filter(x=>x.stage===stage).length;
const columnWeights=[12,6,...['审核','工程下单','采购','生产采购','发货物流','现场处理'].map(stage=>rows.some(x=>x.stage===stage)?11:4),7,10,8,6];const weightSum=columnWeights.reduce((a,b)=>a+b,0);const columnLayout='<colgroup>'+columnWeights.map(w=>'<col style="width:'+w/weightSum*100+'%">').join('')+'</colgroup>';
const body=groups.map(items=>{
const d=items[0],id=d.order||d.project,closed=count(items,'已关闭'),audited=items.filter(x=>x.review?.approved).length;
const dates=items.filter(x=>x.stage!=='已关闭').map(x=>x.stage==='工程下单'?x.orderPlanned||x.planned:x.planned).filter(Boolean).sort();
const pending=items.filter(x=>x.stage!=='已关闭'),owners=[...new Set(items.map(x=>x.trackingOwner||x.owner))];
const stageCell=stage=>`<td class="${count(items,stage)?'stage-active':'stage-empty'}"><span class="stage-count">${count(items,stage)}</span>${departmentTiming(items,stage)}</td>`;
const row=`<tr class="${trackingSelected===id?'order-is-open':''}"><td><strong>${esc(d.project)}</strong><small>${esc(d.customerTier||'客户级别待登记')}</small><small class="mobile-order-status">${esc([...new Set(pending.map(x=>x.department||x.stage))].join(' / ')||'已全部完成')}${dates.length?' · 计划 '+esc(dates[0].slice(5)):''}</small></td><td><b>${items.length}</b></td><td><b>${audited} / ${items.length}</b>${departmentTiming(items,'审核')}</td>${stageCell('工程下单')}${stageCell('采购')}${stageCell('生产采购')}${stageCell('发货物流')}${stageCell('现场处理')}<td><b>${closed} / ${items.length}</b>${count(items,'客户验收')+count(items,'负责人复核')?'<small>待验收 / 复核 '+(count(items,'客户验收')+count(items,'负责人复核'))+'</small>':''}</td><td>${Math.max(0,Math.round((Date.parse(pending.length?today:items.map(x=>x.actual).filter(Boolean).sort().at(-1)||today)-Date.parse(items.map(x=>x.reported).filter(Boolean).sort()[0]||today))/86400000))} 天<small>${pending.length?'未全部完成':'报修至整单完成'}</small>${items.some(overdue)?'<small class="warn">超期 '+items.filter(overdue).length+' 条</small>':''}</td><td>${esc(owners.join('、'))}</td><td><button type="button" data-track-order="${esc(id)}" aria-expanded="${trackingSelected===id}">${trackingSelected===id?'收起详情':'详情'}</button></td></tr>`;
const expanded=trackingSelected===id?`<tr class="order-expanded-row"><td colspan="12"><div class="order-detail-heading"><div><strong>${esc(d.project)} · ${state.nav==='生产中心'?'生产任务':'售后明细'}</strong><small>${esc(d.order||d.project)} · 共 ${items.length} 条 · 已审核 ${audited} 条 · 已完成 ${closed} 条</small></div><span class="tag">${pending.length?'处理中':'已完成'}</span></div>${state.nav==='生产中心'?'<div id="yw-inline-production-tasks"></div>':items.map(trackingIssue).join('')}</td></tr>`:'';
return row+expanded;
}).join('');
trackingPanel.innerHTML=`<div class="toolbar"><h2>售后订单进度 · ${groups.length} 单</h2><button type="button" data-customer-share>发送客户链接</button><small>已审核为累计数量；部门列显示当前所在环节</small></div><div class="table-wrap order-progress-table" aria-label="订单售后汇总进度"><table>${columnLayout}<thead><tr>${['项目名','售后总数','已审核','工程下单','采购','生产','发货','安装','已完成','完成用时','售后专员','详情'].map(t=>'<th>'+t+'</th>').join('')}</tr></thead><tbody>${body||'<tr><td colspan="12">暂无已提交的售后订单。</td></tr>'}</tbody></table></div>`;
mainTable.closest('section').hidden=true;$('.detail').hidden=true;
if(state.nav==='生产中心'){operationPanel.hidden=true;const target=$('#yw-inline-production-tasks');if(target){const selected=groups.find(items=>(items[0].order||items[0].project)===trackingSelected);if(selected){productionOpen=selected[0].order+'|'+selected[0].project;renderProductionQueue();operationPanel.hidden=true;const button=[...operationPanel.querySelectorAll('[data-prod-order]')].find(b=>b.dataset.prodOrder===productionOpen);const section=button?.closest('section');if(section){const children=[...section.children].slice(1);children.forEach(el=>target.appendChild(el));operationPanel.innerHTML='';}else target.innerHTML='<p class="muted">本订单暂无待生产任务，已完成记录见订单流转详情。</p>';}}}
}
root.addEventListener('click',e=>{const b=e.target.closest('[data-track-order]');if(b){trackingSelected=trackingSelected===b.dataset.trackOrder?null:b.dataset.trackOrder;renderTracking(true);persist();}});
function placeInlineEditors(){
for(const [editorId,attribute] of [['yw-operation-editor','data-operation-id'],['yw-engineering-editor','data-engineering-id'],['yw-review-editor','data-review-id']]){
const editor=$('#'+editorId);if(!editor||!editor.innerHTML.trim()||!state.selected)continue;
const button=[...root.querySelectorAll('['+attribute+']')].find(b=>b.getAttribute(attribute)===state.selected);
const ticket=button?.closest('.review-ticket');if(ticket){ticket.after(editor);editor.classList.add('inline-ticket-editor');}
}
}
function toggleAtCurrentPosition(button,callback){const top=button.getBoundingClientRect().top;callback();const attribute=button.hasAttribute('data-operation-id')?'data-operation-id':button.hasAttribute('data-engineering-id')?'data-engineering-id':'data-review-id';const id=button.getAttribute(attribute);const replacement=[...root.querySelectorAll('['+attribute+']')].find(x=>x.getAttribute(attribute)===id);if(replacement){const delta=replacement.getBoundingClientRect().top-top;if(Math.abs(delta)>1)window.scrollBy({top:delta,behavior:'instant'});}}
let productionOpen=null;const productionCostDrafts=new Map();root.addEventListener('input',e=>{if(e.target.hasAttribute('data-prod-cost'))productionCostDrafts.set(e.target.dataset.prodCost,e.target.value);});
function productionStatus(d){return d.production?.status||'待接收';}
function renderProductionQueue(){
for(const sel of ['.totals','.metrics','#yw-stage-panel','.bottom','.detail'])$(sel).hidden=true;
const rows=data.filter(d=>scopeRecord(d)&&d.stage==='生产采购');
const groups=[...new Map(rows.map(d=>[d.order+'|'+d.project,rows.filter(x=>x.order===d.order&&x.project===d.project)])).entries()];
operationPanel.innerHTML='<div class="toolbar"><h2>生产任务 · '+groups.length+' 个订单</h2><small>逐条确认，或勾选后批量处理</small></div>'+groups.map(([key,items])=>`<section><div class="review-ticket"><div><strong>${esc(items[0].project)}</strong><small> · ${esc(items[0].order)}</small><p>${items.length} 条任务 · 待接收 ${items.filter(d=>productionStatus(d)==='待接收').length} · 已接收 ${items.filter(d=>productionStatus(d)==='已接收').length} · 生产中 ${items.filter(d=>productionStatus(d)==='生产中').length}</p></div><button type="button" data-prod-order="${esc(key)}">${productionOpen===key?'收起':'展开任务'}</button></div>${productionOpen===key?`<div id="yw-prod-error" class="import-errors" role="alert"></div><div class="table-wrap"><table class="prod-table"><thead><tr><th>选择</th><th>设备 / 生产任务及操作</th></tr></thead><tbody>${items.map(d=>`<tr><td><input type="checkbox" data-prod-check="${d.id}" aria-label="选择 ${esc(d.product)}"></td><td>${esc(d.product)}<small>${esc(d.engineering?.items||d.review?.purchaseItems||d.review?.method||d.issue)}</small><small>工程单：${esc(d.engineering?.orderNumber||'待补充')} · ${productionStatus(d)}${d.production?.receivedAt?' · 接收 '+d.production.receivedAt:''}</small><div class="prod-item-actions"><button type="button" data-prod-action="receive" data-prod-id="${d.id}" ${productionStatus(d)!=='待接收'?'disabled':''}>确认接收</button><label>预计完成 <input type="date" data-prod-estimate="${d.id}" value="${esc(d.production?.estimatedAt||'')}" min="${today}"></label><label>生产费用（元，本条合计） *<input type="number" min="0" step="0.01" data-prod-cost="${d.id}" value="${esc(productionCostDrafts.get(d.id)??(d.production?.amountCents!=null?(d.production.amountCents/100).toFixed(2):''))}" placeholder="新增加工费，不含采购费"></label><button type="button" data-prod-action="start" data-prod-id="${d.id}" ${productionStatus(d)==='待接收'?'disabled':''}>生产中</button><label>实际完成 <input type="date" data-prod-actual="${d.id}" max="${today}"></label><button type="button" data-prod-action="finish" data-prod-id="${d.id}" ${productionStatus(d)!=='生产中'?'disabled':''}>生产完成，交接仓库打包</button></div><details><summary>问题 / 照片</summary>${reviewProblem(d)}${reviewMedia(d)}</details></td></tr>`).join('')}</tbody></table></div><div class="toolbar production-bulk"><label><input type="checkbox" data-prod-all> 全选本单</label><label>预计 / 实际完成日期 <input type="date" id="yw-prod-date"></label><button type="button" data-prod-action="receive">批量接收</button><button type="button" data-prod-action="start">批量生产中</button><button type="button" data-prod-action="finish">批量完工交仓库</button></div>`:''}</section>`).join('');
}
root.addEventListener('change',e=>{if(e.target.hasAttribute('data-prod-all'))root.querySelectorAll('[data-prod-check]').forEach(c=>c.checked=e.target.checked);});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-prod-order')){productionOpen=productionOpen===b.dataset.prodOrder?null:b.dataset.prodOrder;renderProductionQueue();return;}if(!b.dataset.prodAction)return;const action=b.dataset.prodAction,ids=b.dataset.prodId?[b.dataset.prodId]:[...root.querySelectorAll('[data-prod-check]:checked')].map(c=>c.dataset.prodCheck),items=ids.map(id=>data.find(d=>d.id===id)),date=b.dataset.prodId?(action==='start'?root.querySelector('[data-prod-estimate="'+b.dataset.prodId+'"]')?.value:root.querySelector('[data-prod-actual="'+b.dataset.prodId+'"]')?.value):$('#yw-prod-date').value,error=$('#yw-prod-error');
if(!items.length){error.textContent='请先勾选任务。';return;}if(window.__yifunAccess&&items.some(d=>!d||!window.__yifunAccess.canEditRecord(d))){error.textContent='没有权限处理所选任务。';return;}
if(items.some(d=>!d||d.stage!=='生产采购'||(action==='receive'?productionStatus(d)!=='待接收':action==='start'?productionStatus(d)==='待接收':productionStatus(d)!=='生产中'))){error.textContent='所选任务状态不符合操作条件，请调整勾选；本次未修改任务。';return;}
if(action!=='receive'&&(!validDate(date)||(action==='start'?date<today:date>today)||items.some(d=>action==='finish'&&date<d.production.receivedAt))){error.textContent=action==='start'?'请填写预计完成日期；批量操作使用上方日期。':'请填写实际完成日期，须在接收日期与今天之间。';return;}
const costsById=new Map(items.map(d=>[d.id,costCents(root.querySelector('[data-prod-cost="'+d.id+'"]')?.value??(d.production?.amountCents!=null?d.production.amountCents/100:''))]));if(action!=='receive'&&items.some(d=>costsById.get(d.id)===null)){error.textContent='请为每条所选任务填写生产费用，最多两位小数；无新增费用可填0。批量操作也按每条金额同步。';return;}
if(action!=='receive'&&items.some(d=>{const row=window.__yifunHub.shared.finance.snapshot().rows.find(r=>r.id==='DEPT-生产-'+d.id);return row&&row.paid>costsById.get(d.id);})){error.textContent='生产费用不能低于财务已付金额，请核对金额后再提交。';return;}
for(const d of items){d.production ||= {};if(action==='receive'){Object.assign(d.production,{status:'已接收',receivedAt:today});d.owner=window.__EMPLOYEE__.name;d.ownerId=window.__EMPLOYEE__.id;d.production.person=d.owner;d.awaitingAssignment=false;}else if(action==='start'){Object.assign(d.production,{status:'生产中',startedAt:d.production.startedAt||today,estimatedAt:date});d.planned=date;}else{Object.assign(d.production,{status:'生产完成',completedAt:date,durationDays:Math.max(0,Math.round((Date.parse(date)-Date.parse(d.production.receivedAt))/86400000))});d.stage='发货物流';d.stageEnteredAt=today;d.department='仓库';d.owner='待仓库接单';d.planned='';d.next='仓库打包发货';}if(action!=='receive'){d.production.amountCents=costsById.get(d.id);syncDepartmentCost(d,'生产',d.production.amountCents);productionCostDrafts.delete(d.id);}d.history.push({at:action==='finish'?date:today,actor:'生产部',action:action==='receive'?'接收生产任务':action==='start'?'生产中；预计完成 '+date:'生产完成，交接仓库打包；实际完成 '+date});}
render();notice('已处理 '+items.length+' 条生产任务，订单进度与费用已同步更新。');persist();});
function renderFinanceCenter(){for(const sel of ['.totals','.metrics','#yw-stage-panel','.bottom','.detail'])$(sel).hidden=true;mainTable.closest('section').hidden=true;const rows=data.filter(d=>d.submitted!==false&&scopeRecord(d));operationPanel.innerHTML=`<div class="toolbar"><h2>售后费用台账</h2><small>按工单查看费用承担和采购、物流记录</small></div><div class="table-wrap"><table><thead><tr><th>项目 / 工单</th><th>费用承担</th><th>采购状态 / 单号</th><th>物流单号</th><th>售后专员</th></tr></thead><tbody>${rows.map(d=>`<tr><td>${esc(d.project)}<small>${esc(d.workNo)}</small></td><td>${esc(d.cost||'待确认')}</td><td>${esc(d.purchase?.status||'暂无采购')}<small>${esc(d.purchase?.tracking||'')}</small></td><td>${esc(d.shipment?.tracking||'暂无')}</td><td>${esc(d.trackingOwner||d.owner)}</td></tr>`).join('')}</tbody></table></div>`;}
const importedHidden=new Map();
function renderImportedDepartment(){const hub=document.getElementById('yifun-hub');if(!hub)return false;const main=root.querySelector('main');for(const [el,hidden] of importedHidden)el.hidden=hidden;importedHidden.clear();const routes={'仓库与物流中心':'warehouse','安装中心':'installation','财务中心':'finance'};const route=routes[state.nav],stage={warehouse:'发货物流',installation:'现场处理'}[route],hasCustomerWork=stage&&data.some(d=>d.cloudRequestId&&d.stage===stage&&(d.source==='客户在线提交'||(new URLSearchParams(location.search).get('mode')==='task'&&d.id===new URLSearchParams(location.search).get('record'))));hub.hidden=!route||!!hasCustomerWork;if(!route||hasCustomerWork)return false;for(const el of main.children){if(el===hub||el.classList.contains('heading'))continue;importedHidden.set(el,el.hidden);el.hidden=true;}$('#yw-title').textContent=departmentName(state.nav);$('#yw-subtitle').textContent='仓储物流 · 现场交付 · 费用核对与付款';root.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===state.nav);b.setAttribute('aria-pressed',String(b.dataset.nav===state.nav));});window.__AFTERCARE_INTERNAL__?.refresh();window.__yifunHub?.navigate(route);return true;}

