function renderCustomerPanel(){
 const main=root.querySelector(':scope>.shell>main');if(!customerHost){customerHost=document.createElement('section');customerHost.id='yw-customer-center';customerHost.innerHTML='<iframe title="客户工单中心" src="/aftercare/customers" loading="eager"></iframe>';main.append(customerHost)}
 for(const el of main.children){if(el===customerHost||el.classList.contains('heading'))continue;customerHidden.set(el,el.hidden);el.hidden=true}customerHost.hidden=false;$('#yw-title').textContent='客户工单中心';const headingDate=root.querySelector('.heading>small');if(headingDate)headingDate.textContent=today+' · 中国标准时间';$('#yw-subtitle').textContent='客户在线提交 · 专员检查资料 · 确认后交审核员';root.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===state.nav);b.setAttribute('aria-pressed',String(b.dataset.nav===state.nav))});
}
