(()=>{
const app=document.getElementById('yw-after-sales');
const menu=document.createElement('button');menu.type='button';menu.className='yw-mobile-menu';menu.setAttribute('aria-label','展开部门导航');menu.setAttribute('aria-expanded','false');menu.innerHTML='<i data-lucide="menu" aria-hidden="true"></i>';app.querySelector(':scope>header').append(menu);
menu.addEventListener('click',()=>{const open=app.classList.toggle('mobile-nav-open');menu.setAttribute('aria-expanded',String(open));});
app.querySelector(':scope>.shell>nav').addEventListener('click',e=>{if(e.target.closest('[data-nav]')){app.classList.remove('mobile-nav-open');menu.setAttribute('aria-expanded','false');}});
let pending=false;
function enhance(){pending=false;app.querySelectorAll('.order-progress-table>table').forEach(t=>{const labels=[...t.querySelectorAll(':scope>thead>tr>th')].map(x=>x.textContent);t.querySelectorAll(':scope>tbody>tr:not(.order-expanded-row)').forEach(row=>[...row.children].forEach((td,i)=>{if(td.dataset.label!==labels[i])td.dataset.label=labels[i]||'';}));});}
const observer=new MutationObserver(records=>{if(records.some(r=>r.type==='childList')&&!pending){pending=true;requestAnimationFrame(enhance);}});observer.observe(app,{childList:true,subtree:true});enhance();
if(window.lucide)window.lucide.createIcons({attrs:{width:17,height:17}});
})();


;
(()=>{
const root=document.getElementById('yw-after-sales');
root.dataset.authenticated='true';
const pages=['售后驾驶舱','售后工单中心','售后审核中心','工程下单中心','采购中心','生产中心','仓库与物流中心','安装中心','财务中心','客户工单中心'];
const roles={管理员:{view:pages,write:pages,note:'管理人员权限、查看与操作全部模块'},负责人:{view:pages,write:[],note:'查看全流程和费用，业务操作由各部门完成'},售后专员:{view:[pages[1],pages[9]],write:[pages[1],pages[9]],note:'登记售后、提交审核、跟踪订单完整进度'},审核人员:{view:[pages[1],pages[2],pages[9]],write:[pages[2]],note:'审核问题、保存方案并分派部门'},工程人员:{view:[pages[1],pages[3]],write:[pages[3]],note:'填写工程单、下单组和执行部门'},采购人员:{view:[pages[1],pages[4]],write:[pages[4]],note:'填写采购结果、单号和采购费用'},生产人员:{view:[pages[1],pages[5]],write:[pages[5]],note:'接收生产、排期、登记费用和完工交接'},仓库人员:{view:[pages[6]],write:[pages[6]],note:'仓库到货、齐货及发货跟进'},安装人员:{view:[pages[7]],write:[pages[7]],note:'安装排期、服务记录及交付'},财务人员:{view:[pages[8]],write:[pages[8]],note:'查看部门费用、核对及登记付款'}};
const person=()=>window.__EMPLOYEE__,role=()=>roles[person().role];
function currentPage(){return window.__yifunWorkflow?.page()||root.querySelector('#yw-title')?.textContent;}
function canWrite(page=currentPage()){return !!person()?.active&&role().write.includes(page);}
const account=document.createElement('div');account.className='yw-account';
const label=document.createElement('strong');label.dataset.accountPerson='';label.textContent=person().name+' · '+person().role;account.append(label);
const manage=document.createElement('button');manage.textContent='集团账号管理';manage.hidden=person().role!=='管理员';manage.onclick=()=>{window.parent.location.href='/?view=employees'};account.append(manage);
const shareLink=document.createElement('button');shareLink.textContent='发送客户链接';shareLink.hidden=!role().view.includes('客户工单中心');shareLink.onclick=()=>{window.__yifunWorkflow.navigate('客户工单中心');};account.append(shareLink);
const logout=document.createElement('button');logout.textContent='退出登录';logout.onclick=async()=>{await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});window.parent.location.href='/';};account.append(logout);root.querySelector(':scope>header').append(account);
window.__yifunAccess={canViewPage:p=>role().view.includes(p),canViewRecord:()=>true,canEditRecord:()=>canWrite(),canWrite,current:person};
const readButtons='[data-af-analysis],[data-track-order],[data-close],[data-close-media],[data-review-media],[data-toggle-review-item],[data-operation-id],[data-engineering-id],[data-review-id],[data-tab],[data-go],[data-page],[data-detail],[data-open],[data-service],[data-filter],[data-id],[data-prod-order],[data-template],.yw-mobile-menu';
root.addEventListener('click',e=>{if(e.target.closest('[data-customer-share]')){e.preventDefault();e.stopImmediatePropagation();window.__yifunWorkflow.navigate('客户工单中心');return;}if(e.target.closest('.yw-account,.mobile-app-bottomnav,.yw-mobile-account-sheet'))return;const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){if(!role().view.includes(b.dataset.nav)){e.preventDefault();e.stopImmediatePropagation();}return;}if(b.matches(readButtons))return;if(!canWrite()){e.preventDefault();e.stopImmediatePropagation();alert('当前岗位没有此项操作权限。');}},true);
root.addEventListener('submit',e=>{if(!canWrite()){e.preventDefault();e.stopImmediatePropagation();}},true);
function paint(){root.dataset.accessReadonly=String(!canWrite());root.querySelectorAll(':scope>.shell>nav [data-nav]').forEach(b=>{const hidden=!role().view.includes(b.dataset.nav);if(b.hidden!==hidden)b.hidden=hidden;});if(!canWrite(pages[1]))root.querySelectorAll('#yw-entry').forEach(e=>e.hidden=true);}
let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;paint();});}).observe(root.querySelector('.shell'),{childList:true,subtree:true});
const view=new URLSearchParams(location.search).get('view'),landing=person().role==='售后专员'?'客户工单中心':person().role==='审核人员'?'售后审核中心':role().view[0];window.__yifunWorkflow?.navigate(view==='review'&&role().view.includes('售后审核中心')?'售后审核中心':view==='customer-inbox'&&role().view.includes('客户工单中心')?'客户工单中心':landing);paint();
setInterval(async()=>{try{const j=await(await fetch('/api/aftercare/status',{cache:'no-store'})).json();if(!j.user||j.user.mustChange||j.user.role!==person().role)location.href='/';}catch{}},60000);
})();
;

(()=>{const root=document.getElementById('yw-after-sales');let pending=false;function update(){pending=false;root.querySelectorAll('.table-wrap:not(.order-progress-table)>table:not(.prod-table)').forEach(table=>{const headers=[...table.querySelectorAll(':scope>thead>tr>th')].map(th=>th.textContent.trim());table.querySelectorAll(':scope>tbody>tr').forEach(row=>[...row.children].forEach((td,i)=>{const label=td.colSpan>1?'':headers[i]||'';if(td.dataset.mobileLabel!==label)td.dataset.mobileLabel=label;}));});}new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(update);}}).observe(root,{childList:true,subtree:true});update();})();

;

(()=>{
const root=document.getElementById('yw-after-sales'),header=root.querySelector(':scope>header'),account=root.querySelector('.yw-account'),menu=root.querySelector('.yw-mobile-menu');
if(!account||!menu)return;
const mobile=matchMedia('(max-width:760px)');
const bottom=document.createElement('div');bottom.className='mobile-app-bottomnav';bottom.setAttribute('role','navigation');bottom.setAttribute('aria-label','手机常用导航');bottom.innerHTML=[['work','layout-dashboard','工作'],['orders','clipboard-list','订单'],['modules','grid-2x2','全部'],['profile','circle-user-round','我的']].map(([key,icon,label])=>'<button type="button" data-mobile-destination="'+key+'"><i data-lucide="'+icon+'" aria-hidden="true"></i><span>'+label+'</span></button>').join('');root.append(bottom);
const context=document.createElement('span');context.className='mobile-app-role';header.insertBefore(context,menu);
const sheet=document.createElement('dialog');sheet.className='yw-mobile-account-sheet';sheet.innerHTML='<div class="mobile-sheet-heading"><div><small>我的工作账号</small><h2>账号与权限</h2></div><button type="button" data-mobile-account-close aria-label="关闭账号面板">关闭</button></div><div class="mobile-account-slot"></div><p class="mobile-account-note">员工账号云端验证 · 客户正式工单云端保存</p>';root.append(sheet);
function visiblePages(){return [...root.querySelectorAll(':scope>.shell>nav [data-nav]')].filter(b=>!b.hidden);}
function destinations(){const pages=visiblePages(),current=window.__yifunWorkflow?.page();const work=pages.find(b=>b.dataset.nav==='售后驾驶舱')||pages.find(b=>!['售后工单中心'].includes(b.dataset.nav))||pages[0];const orders=pages.find(b=>b.dataset.nav==='售后工单中心')||pages[0];return {work,orders,current,pages};}
function sync(){const {work,orders,current}=destinations();const person=root.querySelector('[data-account-person]')?.textContent||'';const roleName=person.split(' · ').at(-1);if(context.textContent!==roleName)context.textContent=roleName;const orderLabel=orders?.dataset.nav==='仓库与物流中心'?'项目':orders?.dataset.nav==='安装中心'?'任务':orders?.dataset.nav==='财务中心'?'费用':'订单';const orderSpan=bottom.querySelector('[data-mobile-destination=orders] span');if(orderSpan.textContent!==orderLabel)orderSpan.textContent=orderLabel;bottom.querySelectorAll('button').forEach(b=>{const key=b.dataset.mobileDestination,active=key==='work'?current===work?.dataset.nav:key==='orders'?current===orders?.dataset.nav&&current!==work?.dataset.nav:key==='modules'?root.classList.contains('mobile-nav-open'):sheet.open;b.setAttribute('aria-current',active?'page':'false');});if(root.dataset.authenticated!=='true'){if(sheet.open)sheet.close();if(root.classList.contains('mobile-nav-open'))root.classList.remove('mobile-nav-open');}}
function adapt(){if(mobile.matches){sheet.querySelector('.mobile-account-slot').append(account);menu.setAttribute('aria-label','打开全部模块');}else{sheet.close();header.append(account);menu.setAttribute('aria-label','展开部门导航');}sync();}
bottom.addEventListener('click',e=>{const button=e.target.closest('[data-mobile-destination]');if(!button)return;const key=button.dataset.mobileDestination;if(key==='modules'){menu.click();}else if(key==='profile'){root.classList.remove('mobile-nav-open');menu.setAttribute('aria-expanded','false');sheet.showModal();}else{const target=destinations()[key];if(target){target.click();window.scrollTo({top:0,behavior:'auto'});}}sync();});
sheet.addEventListener('click',e=>{if(e.target.closest('[data-mobile-account-close]'))sheet.close();sync();});
sheet.addEventListener('click',e=>{if(e.target.closest('[data-access-manage],[data-account-password],[data-account-logout]'))sheet.close();},true);
root.addEventListener('focusin',e=>{if(e.target.matches('input,select,textarea'))root.classList.add('mobile-input-focused');});root.addEventListener('focusout',()=>requestAnimationFrame(()=>{if(!root.contains(document.activeElement)||!document.activeElement?.matches('input,select,textarea'))root.classList.remove('mobile-input-focused');}));
let pending=false;new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;sync();});}}).observe(root,{attributes:true,attributeFilter:['data-authenticated','hidden','class','aria-pressed'],childList:true,subtree:true});mobile.addEventListener('change',adapt);sheet.addEventListener('close',sync);adapt();if(window.lucide)lucide.createIcons({attrs:{width:21,height:21}});
})();


;
(()=>{const app=document.getElementById('yw-after-sales'),note=document.createElement('div');note.className='hosted-preview-notice';note.innerHTML='<strong>售后工作台</strong> · 员工账号由云端验证；客户工单已云端保存；各模块已清空演示记录。';app.querySelector(':scope>header').after(note);})();
;
(()=>{
 const root=document.getElementById('yw-after-sales');if(!root)return;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fields=[['model','设备款式'],['problemType','常见问题类型（如异响、卡顿、断裂）'],['region','问题发生区域'],['deviceId','设备编号 / 序列号'],['faultDate','故障发生日期','date'],['activationDate','投入使用日期','date'],['lastRepairCompletedDate','上次维修完成日期','date'],['problemPart','问题部位'],['rootCause','根因分析'],['rootCauseEvidence','根因验证依据'],['correctiveAction','改善措施'],['validationResult','改善验证结果']];
 let items=new Map(),loading=false;
 async function load(){if(loading)return;loading=true;try{const r=await fetch('/api/aftercare/work-items');const j=await r.json();if(r.ok)items=new Map(j.items.map(d=>[d.id,d]));}finally{loading=false;}}
 root.addEventListener('click',async e=>{
  const b=e.target.closest('[data-af-analysis],[data-id],[data-review-id],[data-operation-id],[data-engineering-id]');if(!b)return;
  await load();const id=b.dataset.afAnalysis||b.dataset.id||b.dataset.reviewId||b.dataset.operationId||b.dataset.engineeringId;const d=items.get(id);if(!d)return;
  root.querySelectorAll('.aftercare-analysis').forEach(x=>x.remove());
  const form=document.createElement('form');form.className='aftercare-analysis';form.innerHTML='<h3>故障与根因追踪</h3><p>记录实际故障日期和设备编号，区分使用时长与交付时长。已确认的根因须填写验证依据。</p><div class="fields">'+fields.map(([key,label,type])=>'<label>'+label+'<input name="'+key+'" type="'+(type||'text')+'" value="'+esc(d[key])+'"></label>').join('')+'<label>根因进度<select name="rootCauseStatus">'+['待分析','待验证','已验证'].map(x=>'<option '+(d.rootCauseStatus===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>改善进度<select name="validationStatus">'+['待改善','验证中','已验证'].map(x=>'<option '+(d.validationStatus===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label></div><p class="aftercare-analysis-message" role="status"></p><button type="submit">保存分析记录</button>';
  const target=b.closest('details')||root.querySelector('.detail:not([hidden]),#yw-review-editor:not(:empty),#yw-operation-editor:not(:empty),#yw-engineering-editor:not(:empty)')||b.closest('section');target?.append(form);
  form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const message=form.querySelector('[role=status]');message.textContent='正在保存…';const snapshot={...d,...Object.fromEntries(new FormData(form))};try{const r=await fetch('/api/aftercare/work-items',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[snapshot]})});const j=await r.json();if(!r.ok)throw Error(j.error);message.textContent='已保存，正在刷新最新记录…';location.reload();}catch(err){message.textContent=err.message;}},true);
 });
})();

if(window.parent!==window){const root=document.getElementById('yw-after-sales');let timer;new ResizeObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>window.parent.postMessage({type:'yifun-aftercare-height',height:Math.ceil(root.getBoundingClientRect().height)+24},location.origin),100)}).observe(root);}
